let __v_59 = pyrt::literals::decode("{\"$dict\":[[\"head_bang\",{\"$tuple\":[\"A bang on the head is usually fine, but the next 24 hours are the ones to watch: being sick, being knocked out, or feeling confused or unusually sleepy means an ambulance or A&E rather than wait, and 111 will advise you on anything milder. Are you up and talking normally now, or has anything changed since it happened?\",\"A bumped head hurts for a day or two and an ice pack on it for ten minutes is plenty, but a knock-out, being sick, or feeling confused or sleepier than usual means an ambulance or A&E rather than wait - 111 for anything milder. Are you up and talking normally now, or has anything changed since it happened?\"]}],[\"head_bang_other\",{\"$tuple\":[\"A bang on the head is usually fine, but the next 24 hours are the ones to watch: being sick, being knocked out, or {s} seeming confused or unusually sleepy means an ambulance or A&E rather than wait, and 111 will advise you on anything milder. Is {s} up and talking normally now, or has anything changed since it happened?\",\"A bumped head hurts for a day or two, but a knock-out, being sick, or {s} seeming confused or sleepier than usual means an ambulance or A&E rather than wait - 111 for anything milder. Is {s} up and talking normally now, or has anything changed since it happened?\"]}],[\"head_bang_red\",{\"$tuple\":[\"That is a 999 call rather than wait and see: being knocked out, confused, drowsy or sick after a bang on the head is a head injury until a doctor says otherwise. Keep still and awake, stay with someone, and don't drive yourself.\",\"Ring 999 or 911 now rather than waiting to see: confusion, drowsiness or sickness after a bang on the head is a head injury until a doctor says otherwise. Keep awake and still while you wait, and don't take anything for the headache until someone has seen you.\"]}],[\"head_bang_red_other\",{\"$tuple\":[\"That is a 999 call rather than wait and see: being knocked out, confused, drowsy or sick after a bang on the head is a head injury until a doctor says otherwise. Stay with {o}, keep {o} awake and still, and don't let {o} drive.\",\"Ring 999 or 911 now rather than waiting to see: confusion, drowsiness or sickness after a bang on the head is a head injury until a doctor says otherwise. Keep {o} awake and still, and stay with {o} until help comes.\"]}]]}")?;
